// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address callee;
    ReenterRevert reenterRevert;

    function setUp() public {
        c = new C();
        reenterRevert = new ReenterRevert(address(c));
        callee = address(reenterRevert);
    }

    function testFuzz_property(bytes memory _data) public {
        // The reference always reverts when callee reenters forward and then reverts.
        vm.assume(_data.length > 0); // optional, but helps focus
        bytes memory innerData = abi.encodeWithSignature("forward(address,bytes)", address(0), "");
        reenterRevert.setInnerData(innerData);
        vm.expectRevert();
        c.forward(callee, _data);
        assertTrue(true);
    }
}

contract ReenterRevert {
    address immutable target;
    bytes innerData;

    constructor(address _target) { target = _target; }

    function setInnerData(bytes memory _innerData) public { innerData = _innerData; }

    fallback() external {
        (bool success,) = target.call(innerData);
        require(success); // This reentrant call must succeed
        revert(); // Then revert
    }
}

